function sha256(text) {
  const bytes = [];
  for (let index = 0; index < text.length; index++) {
    let code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff && index + 1 < text.length) {
      const low = text.charCodeAt(index + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        code = 0x10000 + ((code - 0xd800) << 10) + low - 0xdc00;
        index++;
      } else code = 0xfffd;
    } else if (code >= 0xd800 && code <= 0xdfff) code = 0xfffd;
    if (code < 0x80) bytes.push(code);
    else if (code < 0x800) bytes.push(0xc0 | (code >>> 6), 0x80 | (code & 63));
    else if (code < 0x10000) bytes.push(0xe0 | (code >>> 12), 0x80 | ((code >>> 6) & 63), 0x80 | (code & 63));
    else bytes.push(0xf0 | (code >>> 18), 0x80 | ((code >>> 12) & 63), 0x80 | ((code >>> 6) & 63), 0x80 | (code & 63));
  }
  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const high = Math.floor(bitLength / 0x100000000), low = bitLength >>> 0;
  for (let n = 24; n >= 0; n -= 8) bytes.push((high >>> n) & 255);
  for (let n = 24; n >= 0; n -= 8) bytes.push((low >>> n) & 255);
  const constants = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const state = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const rotr = (n, by) => (n >>> by) | (n << (32 - by));
  for (let offset = 0; offset < bytes.length; offset += 64) {
    const words = new Array(64);
    for (let j = 0; j < 16; j++) {
      const p = offset + j * 4;
      words[j] = (bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3];
    }
    for (let j = 16; j < 64; j++) {
      const a = words[j - 15], b = words[j - 2];
      words[j] = (words[j - 16] + (rotr(a,7)^rotr(a,18)^(a>>>3)) + words[j - 7] + (rotr(b,17)^rotr(b,19)^(b>>>10))) | 0;
    }
    let [a,b,c,d,e,f,g,h] = state;
    for (let j = 0; j < 64; j++) {
      const t1 = (h + (rotr(e,6)^rotr(e,11)^rotr(e,25)) + ((e & f)^((~e)&g)) + constants[j] + words[j]) | 0;
      const t2 = ((rotr(a,2)^rotr(a,13)^rotr(a,22)) + ((a & b)^(a & c)^(b & c))) | 0;
      h=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
    }
    for (const [i,v] of [a,b,c,d,e,f,g,h].entries()) state[i] = (state[i] + v) | 0;
  }
  return state.map(n=>(n>>>0).toString(16).padStart(8,"0")).join("");
}

function resolveFinalReceiptGroupIds(context, sha256) {
  const hash=value=>sha256(JSON.stringify(value));
  if(!context || !Array.isArray(context.receiptRefs) || !Array.isArray(context.receiptGroups) ||
     !Array.isArray(context.artifactFiles)) throw Error("missing actual receipt reference context");
  const files=new Map(context.artifactFiles.map(f=>[f.path,f]));
  if(files.size!==136 || context.artifactFiles.length!==136) throw Error("complete artifact slots");
  return context.receiptRefs.map(ref=>{
    if(!ref || typeof ref.groupId!=="string" || typeof ref.releaseGroupPointer!=="string") throw Error("group ref shape");
    const index=context.receiptGroups.findIndex(g=>g.id===ref.groupId);
    if(index<0 || ref.releaseGroupPointer!=="/receiptGroups/"+index) throw Error("group pointer");
    const g=context.receiptGroups[index];
    if(g.authenticated!==true || ref.receiptGroupSha256!==hash(g)) throw Error("exact authenticated group value");
    for(const bound of g.authenticatedFileReferences??[]) {
      const f=files.get(bound.path);
      if(!f || bound.sha256!==f.sha256 || bound.bytes!==f.bytes ||
         (bound.retainedBlob??null)!==(f.retainedBlob??null) ||
         hash(bound.receiptOrEnvelopeRef??null)!==hash(f.receiptOrEnvelopeRef??null)) throw Error("group artifact envelope");
    }
    if((g.authenticatedFileReferences??[]).length!==g.files.length) throw Error("group artifact count");
    if(!(g.resolvedSelectors??[]).every(s=>s.verified===true)) throw Error("group selectors");
    if(!(g.currentSelectors??[]).every(s=>s.verified===true)) throw Error("group current selectors");
    if((g.id==="host-boundary" || g.id==="name-index") && !(g.workflowLogEvidence?.length>0)) throw Error("log-only evidence absent");
    return ref.groupId;
  });
}

function bindFinalReleaseArtifacts(draft, files, context, hash) {
  const copy = value => JSON.parse(JSON.stringify(value));
  const equal = (a,b,label) => { if (JSON.stringify(a)!==JSON.stringify(b)) throw Error(label); };
  const need = (ok,label) => { if (!ok) throw Error(label); };
  const own = (o,k) => Object.prototype.hasOwnProperty.call(o,k);
  const at = (value, pointer) => {
    if (pointer==="") return value;
    need(typeof pointer==="string" && pointer.startsWith("/"), "invalid pointer");
    return pointer.slice(1).split("/").reduce((o,k) => {
      k=k.replace(/~1/g,"/").replace(/~0/g,"~");
      need(o!==null && typeof o==="object" && own(o,k), "missing pointer "+pointer);
      return o[k];
    }, value);
  };
  const bytes = s => unescape(encodeURIComponent(s)).length;
  const r=copy(draft), required=r.artifactBindings.files.map(x=>x.path);
  need(required.length===136 && new Set(required).size===136,"exact catalog slots");
  const file = path => {
    const f=files[path]; need(f && f.path===path,"file "+path);
    need(/^[a-f0-9]{64}$/.test(f.sha256) && Number.isSafeInteger(f.bytes) && f.bytes>=0, "file envelope "+path);
    need((typeof f.retainedBlob==="string" && /^[a-f0-9]{40}$/.test(f.retainedBlob)) || f.receiptOrEnvelopeRef, "immutable envelope "+path);
    if (own(f,"content")) {
      need(typeof f.content==="string" && hash(f.content)===f.sha256 && bytes(f.content)===f.bytes,"raw bytes "+path);
      if (own(f,"value")) equal(JSON.parse(f.content), f.value, "parsed raw "+path);
    }
    return f;
  };
  const envelope = path => {
    const f=file(path);
    return {path,sha256:f.sha256,bytes:f.bytes,retainedBlob:f.retainedBlob??null,
      receiptOrEnvelopeRef:copy(f.receiptOrEnvelopeRef??null)};
  };
  const value = (path,pointer="") => {
    const f=file(path); need(own(f,"value"),"authentic JSON required "+path);
    return at(f.value,pointer);
  };
  const selector = s => {
    const v=value(s.file,s.jsonPointer), serialized=JSON.stringify(v);
    need(serialized!==undefined,"undefined selector");
    const e={file:s.file,jsonPointer:s.jsonPointer,verified:true,
      fileEnvelope:envelope(s.file),jsonValueSha256:hash(serialized),
      jsonValueUtf8Bytes:bytes(serialized),jsonValueEncoding:"JSON.stringify(exact parsed value), UTF-8, no LF"};
    if(bytes(serialized)<=8192) { e.value=copy(v); e.valueRepresentation="exact-parsed-json-value"; }
    else {
      e.valueRepresentation="authenticated-raw-file-and-exact-json-value-hash";
      e.valueReference={...envelope(s.file),jsonPointer:s.jsonPointer,
        jsonValueSha256:e.jsonValueSha256,jsonValueUtf8Bytes:e.jsonValueUtf8Bytes};
    }
    return e;
  };
  r.artifactBindings.files=required.map(path=>({...envelope(path),authentication:file(path).authentication??"authenticated-returned-file-envelope"}));
  r.artifactBindings.supplementalReturnedFiles=(context.supplementalPaths??[]).map(envelope);
  r.artifactBindings.observedComplete=true;
  const groupRef = (index,g) => ({
    groupId:g.id,releaseGroupPointer:"/receiptGroups/"+index,
    effectiveStaticCatalogSha256:hash(JSON.stringify({id:g.id,files:g.files,required:g.required,selectors:g.selectors,limit:g.limit})),
    fileReferences:g.files.map(envelope),
    resolvedSelectorReferences:(g.resolvedSelectors??[]).map((s,i)=>({
      releasePointer:"/receiptGroups/"+index+"/resolvedSelectors/"+i,
      file:s.file,jsonPointer:s.jsonPointer,sha256:s.fileEnvelope.sha256,jsonValueSha256:s.jsonValueSha256
    })),
    currentSelectorReferences:(g.currentSelectors??[]).map((s,i)=>({
      releasePointer:"/receiptGroups/"+index+"/currentSelectors/"+i,
      file:s.file,jsonPointer:s.jsonPointer,sha256:s.fileEnvelope.sha256,jsonValueSha256:s.jsonValueSha256
    })),
    logEvidenceReferences:copy((context.logEvidence??[]).filter(x=>x.groupIds.includes(g.id))),
    limit:g.limit
  });
  for (const [index,g] of r.receiptGroups.entries()) {
    for(const path of g.files) file(path);
    g.resolvedSelectors=(g.resolvedSelectors??[]).map(selector);
    if(g.currentSelectors) g.currentSelectors=g.currentSelectors.map(selector);
    if(g.id==="host-boundary" || g.id==="name-index") {
      const logs=(context.logEvidence??[]).filter(x=>x.groupIds.includes(g.id));
      const ownership=(r.execution.logOnlyGateOwnership??[]).filter(x=>x.receiptGroupId===g.id);
      need(ownership.length===1 && ownership[0].executionPointer==="/execution/priorExecution" &&
        ownership[0].stepNumber===22, "explicit original log ownership "+g.id);
      const producer=at(r,ownership[0].executionPointer);
      need(producer.expectedRunId===38015134511 && producer.expectedWorkflowId===378853677 &&
        producer.expectedHeadSha===r.source.sourceRef && producer.compilerJobId===114103608774 &&
        producer.compilerConclusion==="cancelled" && producer.providerConclusion==="skipped",
        "preserved original execution "+g.id);
      need(logs.length>0 && logs.every(x=>x.conclusion==="success" &&
        x.stepNumber===ownership[0].stepNumber && x.workflowBlob===producer.workflowSourceBlob &&
        x.jobId===producer.compilerJobId && x.runId===producer.expectedRunId &&
        x.sourceRef===r.source.sourceRef && x.logReference), "actual original log-only gate "+g.id);
      for(const x of logs) equal(x.logReference,producer.compilerJobLog,"exact original log envelope "+g.id);
      g.workflowLogEvidence=copy(logs);
    }
    if(g.currentBoundarySelectors) {
      g.currentBoundaryObservations=g.currentBoundarySelectors.map((b,i)=>{
        const kind=value(b.file,b.jsonPointers[0]), rows=value(b.file,b.hashInputPointer);
        equal(kind,b.expectedSourceKind,"source kind "+i);
        equal(rows.map(x=>x.name),b.expectedRowNames,"empty names "+i);
        for(const row of rows) {
          for(const k of b.requiredRowFields) need(own(row,k),"empty field "+k);
          need(row.bodyIsTypedEmptyResult===true,"direct typed empty body");
          equal(row.resultType,row.declarationResultType,"typed empty declared result");
          equal(row.runtimeParameters,row.name==="sh1EmptyFresh"?["value","emptyResult"]:["value"],"typed empty parameters");
        }
        const digest=hash(JSON.stringify(rows));
        equal(value(b.binderFile,b.binderSha256Pointer),digest,"empty eliminations hash "+i);
        return {sourceKind:kind,file:b.file,fileEnvelope:envelope(b.file),
          jsonPointer:b.hashInputPointer,eliminationsSha256:digest,rowCount:rows.length,
          names:rows.map(x=>x.name),directTypedEmptyBody:true,resultTypesMatch:true,
          actualRuntimeParametersVerified:true,binderFileEnvelope:envelope(b.binderFile),
          binderJsonPointer:b.binderSha256Pointer,verified:true};
      });
      need(g.currentBoundaryObservations.length===8,"eight source-empty boundaries");
    }
    if(g.id==="strict-binder") {
      need(!own(g,"currentEvidenceProducer"),"fresh current binder producer reference");
      g.currentEvidenceProducer={
        executionPointer:"/execution/evidenceProducer",
        executionValueSha256:hash(JSON.stringify(r.execution.evidenceProducer)),
        binderPointer:"/execution/evidenceProducer/binder",
        repairPointer:"/execution/evidenceProducerRepair",
        repairValueSha256:hash(JSON.stringify(r.execution.evidenceProducerRepair)),
        sourceBlobMeaning:"Original generation-recipe source retained as the reviewed base of the exact evidence-producer correction."
      };
    }
    g.status="authenticated-current-qualified-execution-evidence";
    g.authenticated=true;
    g.authenticatedFileReferences=g.files.map(envelope);
    g.actualEvidenceReference=groupRef(index,g);
  }
  const q=value("qualification.json"), b=value("strict-enforcement-evidence.json"), p=value("kernel-admissions.json");
  equal(q.evidence,"compiler-qualified-current-source-fixed-point","actual completed qualification kind");
  need(q.strictSourceEnforced===true && q.strictTargetAdmissionEnforced===true && q.runtimeIrTypingEnforced===true,"actual enforced compiler boundaries");
  need(q.strictSh1Qualified===false && q.semanticContractQualified===false && q.provider.status==="not-attempted" && q.provider.kernelChecked===false,"preserved produced qualification nonclaims");
  need(b.kind==="psc0-strict-enforcement-qualified-evidence" && b.strictSh1Qualified===false && b.semanticContractQualified===false && b.providerChecked===false && b.sourceOrigins.semanticCorrespondenceDischarged===false,"preserved actual binder nonclaims");
  need(b.sourceEnforcementQualified===true && b.targetAdmissionQualified===true && b.enabledRuntimeFiniteConformanceQualified===true && b.genericFunctionValueFiniteConformanceQualified===true,"actual binder completion");
  equal(q.strictSourceAndRuntimeConformanceGenerations,["N1","C1","C2","C3"],"actual four conformance generations");
  equal(q.originalIrCheckedBuilds,["C2","C3"],"actual full generated original IR boundaries");
  equal(q.sourceRef,r.source.sourceRef,"q source");
  equal(q.sourceClosureSha256,context.sourceClosureSha256,"q closure");
  equal(q.strictEnforcementEvidence.sha256,file("strict-enforcement-evidence.json").sha256,"binder raw hash");
  const {report,sha256,...embedded}=q.strictEnforcementEvidence;
  equal(embedded,b,"binder embedded exact value");
  equal(p.sourceRef,q.sourceRef,"provider source");
  equal(p.sourceClosureSha256,q.sourceClosureSha256,"provider closure");
  equal(p.compilerSha256,q.c2CompilerSha256,"provider compiler");
  equal(q.c2CompilerSha256,q.c3CompilerSha256,"fixed point compiler");
  for(const e of r.equalityBindings.sourceRef) equal(value(e.file,e.jsonPointer),q.sourceRef,"source vector");
  for(const e of r.equalityBindings.sourceClosure) equal(value(e.file,e.jsonPointer),q.sourceClosureSha256,"closure vector");
  for(const k of ["c1Executor","c2Executor","c3Executor"]) {
    const e=r.equalityBindings[k]; equal(value(e.left.file,e.left.jsonPointer),
      e.right?value(e.right.file,e.right.jsonPointer):e.expected,k);
  }
  for(const e of r.equalityBindings.c2C3ComparedTuple) equal(value(e.file,e.jsonPointer),q.artifacts,"fixed point tuple");
  for(const set of r.equalityBindings.nativeTsJsParity) {
    const v=value(set[0].file,set[0].jsonPointer);
    for(const e of set) equal(value(e.file,e.jsonPointer),v,"native output parity");
  }
  const canonical=value(r.equalityBindings.currentCanonical.grammar.file,r.equalityBindings.currentCanonical.grammar.jsonPointer);
  for(const e of r.equalityBindings.currentCanonical.generations) equal(value(e.file,e.jsonPointer),canonical,"current canonical grammar");
  const recipe=value("development/N1/receipt.json","/recipe");
  need(recipe.files.length===48,"48 recipe sources");
  equal(hash(JSON.stringify(recipe.files)),context.recipeSha256,"actual recipe hash");
  equal(recipe.files,context.currentRecipeFiles,"recipe matches exact source prediction");
  for(const source of r.recipe.sourceFiles) {
    const found=recipe.files.find(f=>f.path===source.path); need(found,"recipe source path "+source.path);
    if(source.sha256!==null) equal(source.sha256,found.sha256,"pinned recipe source");
    source.sha256=found.sha256;
  }
  r.recipe.exactObject=copy(recipe); r.recipe.sha256=context.recipeSha256;
  r.recipe.actualToolchain=copy(q.toolchain); r.recipe.actualTypeScriptProfile=copy(q.typescriptProfile);
  r.recipe.expectedCurrentSourceRecipe.actualCurrentReceiptBound=true;
  r.recipe.expectedCurrentSourceRecipe.status="matched-authenticated-current-generation-receipts";
  for(const g of r.generations) {
    const path=g.directory+"/receipt.json", receipt=value(path);
    equal(receipt.recipe,recipe,"generation recipe "+g.name);
    equal(receipt.toolchain,q.toolchain,"generation toolchain "+g.name);
    equal(receipt.typescriptProfile,q.typescriptProfile,"generation TS profile "+g.name);
    equal(receipt.artifacts.javascriptSha256,file(g.directory+"/index.js").sha256,"generation JS "+g.name);
    equal(receipt.artifacts.typescriptSha256,file(g.directory+"/index.ts").sha256,"generation TS "+g.name);
    g.status="authenticated-current-source-generation";
    g.receipt=envelope(path);
    g.actualCompilerSha256=value(g.outputCompiler.file,g.outputCompiler.jsonPointer);
    g.actualExecutingCompilerSha256=value(g.executingCompiler.file,g.executingCompiler.jsonPointer);
    g.actualTypeScriptSha256=value(g.outputTypeScript.file,g.outputTypeScript.jsonPointer);
    g.actualRecipeSha256=context.recipeSha256;
    if(g.outputCanonical) g.actualCanonicalSurfaceSourceSha256=value(g.outputCanonical.file,g.outputCanonical.jsonPointer);
    if(g.outputAdmissions) g.actualCanonicalAdmissionsSha256=value(g.outputAdmissions.file,g.outputAdmissions.jsonPointer);
  }
  const manifest=context.sourceClosureManifest;
  need(Array.isArray(manifest) && manifest.length>0,"actual raw closure");
  equal(hash(JSON.stringify(manifest)),q.sourceClosureSha256,"raw closure identity");
  r.source.sourceClosureSha256=q.sourceClosureSha256;
  r.source.orderedRawClosure=copy(manifest);
  need(/^[a-f0-9]{64}$/.test(b.sourceInputsSha256),"actual atomic source input digest");
  r.source.sourceInputsSha256=b.sourceInputsSha256;
  r.source.sourceInputsDigestReference={...envelope("strict-enforcement-evidence.json"),jsonPointer:"/sourceInputsSha256"};
  r.source.expectedUnchangedClosure.actualCurrentReceiptBound=true;
  r.source.expectedUnchangedClosure.status="matched-authenticated-current-generation-receipts";
  r.equalityBindings.providerToQualification.qualificationFileHash=file("qualification.json").sha256;
  r.equalityBindings.providerToQualification.providerFileHash=file("kernel-admissions.json").sha256;
  r.equalityBindings.verified=true;
  need(p.accepted===true && p.emissionWasGatedByThisCheck===false,"actual provider decision");
  equal(p.provider.sourceRef,r.provider.expectedSourceRef,"provider pin");
  need(p.streams.length>0 && p.streams.every(s=>s.result.accepted===true),"all actual provider streams");
  const labels=r.provider.labels.map(label=>{
    const d=label.digestSource;
    let digest;
    if(d.jsonPointer) digest=value(d.file,d.jsonPointer);
    else {
      const matches=value(d.file,d.arrayPointer).filter(x=>Object.entries(d.where).every(([k,v])=>x[k]===v));
      need(matches.length===1,"unique provider digest source"); digest=matches[0][d.member];
    }
    equal(file(label.path).sha256,digest,"provider input raw digest");
    const matches=p.streams.map((s,i)=>({s,i})).filter(x=>x.s.canonicalAdmissionsSha256===digest && x.s.artifacts.includes(label.label));
    need(matches.length===1,"unique provider label decision "+label.label);
    return {...label,canonicalAdmissionsSha256:digest,providerStreamIndex:matches[0].i,accepted:true,
      inputFileEnvelope:envelope(label.path),
      actualDecisionReference:{...envelope("kernel-admissions.json"),jsonPointer:"/streams/"+matches[0].i}};
  });
  equal(p.streams.flatMap(s=>s.artifacts).slice().sort(),labels.map(l=>l.label).slice().sort(),"exact eight provider labels");
  r.provider.labels=labels; r.provider.labeledInputCount=labels.length;
  r.provider.uniqueStreamCount=p.streams.length; r.provider.identity=copy(p.provider);
  r.provider.streams=p.streams.map((s,i)=>({...copy(s),accepted:s.result.accepted,
    jsonPointer:"/streams/"+i,decisionReceiptRef:{...envelope("kernel-admissions.json"),jsonPointer:"/streams/"+i}}));
  r.provider.receipt=envelope("kernel-admissions.json");
  r.provider.status="actual-selected-provider-accepted-all-returned-streams";
  r.provider.accepted=true;
  r.execution.qualificationFile=envelope("qualification.json");
  r.execution.strictBinderFile=envelope("strict-enforcement-evidence.json");
  r.execution.providerFile=envelope("kernel-admissions.json");
  need(r.qualification.strictSh1Qualified===false && r.correspondenceDispositions.every(x=>x.strictSh1Discharged===false) && r.stageDispositions.every(x=>x.strictDischarged===false),"binding alone must not promote disposition");
  {
  // Exact shared evidence-completion validation; pure metadata only.
  const R=r, T=context.correspondenceTransport, P=context.correspondenceProcedure, A=context.actualEvidence;
  need(T && P && A,"required actual evidence-completion context");
  const K={
  "sourceRef": "1fa5559a72b293defc56ef7e7020cf82d4b44b79",
